// La dirección del CRM, de la tabla configuracion
const config = Object.fromEntries($input.all().map((i) => [i.json.clave, i.json.valor]));
if (!config.crm_url) throw new Error('Falta la fila crm_url en la tabla configuracion');
return [{ json: { crm_url: config.crm_url.replace(/\/$/, '') } }];

// Los avisos de "lead prioritario" que armó el CRM. Si no hay, sigue un ítem vacío para llegar a las alarmas
const r = $('Pedir avisos').first().json;
const correos = r.statusCode === 200 ? r.body?.correos : null;
if (!Array.isArray(correos) || !correos.length) return [{ json: {} }];
return correos.map((c) => ({ json: { ref: c.id, para: c.para, quien: c.quien, asunto: c.asunto, texto: c.texto } }));

// Solo se mandan los avisos que esta ejecución logró reservar (una respuesta por aviso, en el mismo orden):
// si dos ejecuciones se cruzan, cada aviso sale una sola vez
const correos = $('Correos a enviar').all().map((i) => i.json);
const reservas = $input.all().map((i) => i.json);
const listos = correos.filter((c, i) => reservas[i]?.reservado === true);
return listos.length ? listos.map((c) => ({ json: c })) : [{ json: {} }];

// Por cada aviso: si el correo salió se confirma; si no, se suelta para que la vuelta siguiente lo intente
const correos = $('Solo los reservados').all().map((i) => i.json);
const resultados = $input.all().map((i) => i.json);
// Si el subflujo 00b falló entero (por ejemplo, faltan filas en destinos_prueba), no salió ninguno
if (resultados.some((r) => !('ok' in r))) {
  const motivo = resultados.find((r) => r.error)?.error;
  return correos.map((c) => ({ json: { id: c.ref, accion: 'soltar_aviso', error: motivo?.message ?? motivo ?? 'falló el envío' } }));
}
return resultados.map((e) => ({ json: { id: e.ref, accion: e.ok ? 'confirmar_aviso' : 'soltar_aviso', error: e.error } }));

// Todas las alarmas de esta vuelta en un solo aviso, sin nombres de clientes (solo cuentas y códigos).
// Lo que se repite suena la primera vez y luego cada 30 minutos; n8n guarda en la memoria del flujo qué ya
// avisó (esa memoria solo existe cuando el flujo corre activo, no a mano).
const memoria = $getWorkflowStaticData('global');
const ahora = Date.now();
const MEDIA_HORA = 30 * 60 * 1000;
const hoy = $now.toFormat('yyyy-MM-dd');
const alarmas = [];
const cadaMediaHora = (clave, texto) => {
  if (!memoria[clave] || ahora - memoria[clave] >= MEDIA_HORA) {
    memoria[clave] = ahora;
    alarmas.push(texto);
  }
};

// n8n reescribe los mensajes con códigos de red (ECONNREFUSED...): se traducen antes (como en 01d)
const traducir = (m) =>
  /ECONNREFUSED|ECONNRESET/.test(m) ? 'el CRM no contesta: está apagado o sin conexión'
  : /ETIMEDOUT|ESOCKETTIMEDOUT|timeout/i.test(m) ? 'tardó demasiado en contestar'
  : /ENOTFOUND|EAI_AGAIN/.test(m) ? 'no se encontró la dirección'
  : /401|authoriz/i.test(m) ? 'la llave no coincide (AUTOMATIZACIONES_TOKEN en n8n y en el CRM)'
  : m.slice(0, 150);
const funciono = (r) => r?.statusCode === 200 && r.body && typeof r.body === 'object';
const motivo = (r) => (r?.statusCode ? `el CRM respondió ${r.statusCode}${r.body?.error ? `: ${r.body.error}` : ''}`
  : traducir(String(r?.error?.message ?? r?.error ?? 'respuesta inesperada')));

const cal = $('Calificar').first().json;
const av = $('Pedir avisos').first().json;

// 1. La calificación falla. Si los dos pedidos fallaron como falla todo el CRM (no contesta, la llave no
//    coincide o un error 5xx), la alarma ya la da 01d y aquí no se repite. Cualquier otra respuesta (por
//    ejemplo, un 404: la ventanilla no existe en ese despliegue) solo la ve el 08
const comoTodoElCrm = (r) => !r?.statusCode || r.statusCode === 401 || r.statusCode >= 500;
if (!funciono(cal)) {
  if (funciono(av) || !comoTodoElCrm(cal) || !comoTodoElCrm(av)) {
    cadaMediaHora('alarmaCalificar', `la calificación falla (${motivo(cal)}): los leads quedan en el CRM sin prioridad`);
  }
} else {
  delete memoria.alarmaCalificar;
  const r = cal.body;
  if (r.error_de_configuracion) {
    // 2. Claude rechaza los pedidos y no se arregla esperando
    cadaMediaHora('alarmaConfiguracion', `Claude rechaza los pedidos (${r.error}): revisa el saldo de la cuenta de Anthropic, la llave ANTHROPIC_API_KEY del CRM y el modelo. No se califica ningún lead`);
  } else if (r.calificados > 0 || r.fin === 'fallo_claude') {
    // Claude volvió a aceptar pedidos. En una vuelta sin leads ("nada") no se sabe: la memoria se queda
    delete memoria.alarmaConfiguracion;
  }
  if (r.fin === 'sin_cupo') {
    // 3. El tope del día: una vez al día (y no suena además la de atrasados)
    if (memoria.alarmaSinCupo !== hoy) {
      memoria.alarmaSinCupo = hoy;
      alarmas.push('se llegó al tope de 300 llamadas a la IA de hoy: no se califican más leads hasta mañana (si no hubo muchos leads, revisa si alguien está llenando el formulario)');
    }
  } else if (r.atrasadas > 0 && !r.error_de_configuracion) {
    // 4. Leads ya intentados que llevan más de 30 minutos sin prioridad (Claude caído o lento)
    cadaMediaHora('alarmaAtrasadas', `${r.atrasadas} lead(s) llevan más de 30 minutos sin poder calificarse${r.error ? ` (último error de Claude: ${r.error})` : ''}; se reintentan solos`);
  } else if (!r.atrasadas) {
    delete memoria.alarmaAtrasadas;
  }
}

memoria.atascadosAvisados ??= [];
memoria.terminadasAvisadas ??= [];
const anotarAtascados = (ids) => {
  memoria.atascadosAvisados = [...memoria.atascadosAvisados, ...ids].slice(-200);
};

if (funciono(av)) {
  delete memoria.alarmaAvisos;
  // 5. Avisos sin confirmar (n8n se detuvo a la mitad): uno por aviso, una sola vez
  const atascados = (av.body.atascados ?? []).filter((x) => !memoria.atascadosAvisados.includes(x.calificacion_id));
  if (atascados.length) {
    anotarAtascados(atascados.map((x) => x.calificacion_id));
    const ejecuciones = [...new Set(atascados.map((x) => x.ejecucion))].join(', ');
    alarmas.push(`${atascados.length} aviso(s) de lead prioritario quedaron sin confirmar (ejecución ${ejecuciones} de 08): revisa esa ejecución antes de reenviar, puede que el correo sí haya salido`);
  }
  // 6. Leads que terminaron sin prioridad (fallidos, rechazados o vencidos): una vez cada uno
  const terminadas = (av.body.terminadas_mal ?? []).filter((x) => !memoria.terminadasAvisadas.includes(x.calificacion_id));
  if (terminadas.length) {
    memoria.terminadasAvisadas = [...memoria.terminadasAvisadas, ...terminadas.map((x) => x.calificacion_id)].slice(-500);
    const cuenta = {};
    for (const t of terminadas) cuenta[t.estado] = (cuenta[t.estado] ?? 0) + 1;
    const detalle = Object.entries(cuenta).map(([estado, n]) => `${n} ${estado}`).join(', ');
    const errores = [...new Set(terminadas.map((t) => t.error).filter(Boolean))].join(', ');
    alarmas.push(`${terminadas.length} lead(s) se quedaron sin calificar (${detalle}${errores ? `; errores: ${errores}` : ''}): siguen en el CRM, sin prioridad`);
  }
} else if (funciono(cal) || !comoTodoElCrm(av)) {
  cadaMediaHora('alarmaAvisos', `no se pudieron revisar los avisos de lead prioritario (${motivo(av)})`);
}

// Reservas que fallaron (no un "no" normal porque otra ejecución lo reservó: un error). Ese aviso no sale en
// esta vuelta; si sigue fallando, a las 24 horas deja de estar pendiente sin dejar rastro: por eso suena
if ($('Reservar aviso').isExecuted) {
  const fallidas = $('Reservar aviso').all().filter((i) => i.json.error);
  if (fallidas.length) cadaMediaHora('alarmaReserva', `no se pudieron reservar ${fallidas.length} aviso(s) de lead prioritario (${traducir(String(fallidas[0].json.error?.message ?? fallidas[0].json.error))}); se reintentan en la vuelta siguiente`);
}

// 7. Correos de aviso que no salieron: se soltaron y se reintentan en la vuelta siguiente
if ($('Decidir').isExecuted) {
  const soltados = $('Decidir').all().filter((i) => i.json.accion === 'soltar_aviso');
  if (!soltados.length) delete memoria.alarmaCorreo;
  if (soltados.length) cadaMediaHora('alarmaCorreo', `no salieron ${soltados.length} aviso(s) de lead prioritario (${traducir(String(soltados[0].json.error ?? ''))}); se reintentan en la vuelta siguiente`);
}

// 8. Lo que no se pudo anotar en el CRM. Una respuesta por pedido, en el mismo orden (este paso corre una
//    sola vez: aquí no sirve emparejar ítem por ítem). Esos avisos aparecerán como atascados: se marcan como
//    ya avisados para que una sola falla no suene dos veces
if ($('Anotar en el CRM').isExecuted) {
  const pedidos = $('Decidir').all();
  const anotar = $('Anotar en el CRM').all().map((item, i) => ({ r: item.json, pedido: pedidos[i]?.json ?? {} }));
  const sinConfirmar = anotar.filter(({ r, pedido }) => pedido.accion === 'confirmar_aviso' && (r.error || r.confirmado !== true));
  const sinSoltar = anotar.filter(({ r, pedido }) => pedido.accion === 'soltar_aviso' && (r.error || r.soltado !== true));
  anotarAtascados([...sinConfirmar, ...sinSoltar].map(({ pedido }) => pedido.id));
  if (sinConfirmar.length) alarmas.push(`${sinConfirmar.length} aviso(s) salieron pero el CRM no los anotó: no se repiten solos`);
  if (sinSoltar.length) alarmas.push(`${sinSoltar.length} aviso(s) que no salieron no se pudieron soltar: no se reintentan solos`);
}

return [{ json: { alarma: alarmas.length ? `08 Calificar leads: ${alarmas.join('; ')}.` : null } }];
